# Exploratory linear-by-Cox coefficient-product mediation, adapted from border.
binary_exposures<-c('bmonth_winter_summer','bmonth_spring_autumn')
mediation_data<-function(d,x,m,y=NULL){vars<-unique(c(x,m,covars,if(!is.null(y))paste0(y,c('.t2e','.Yt2e'))));if(!is.null(y))d<-ensure_outcome(d,y);z<-complete_model_data(d,vars);if(nrow(z)<1000||length(unique(z[[x]]))<2||length(unique(z[[m]]))<2)return(NULL);if(!is.null(y)&&sum(z[[paste0(y,'.Yt2e')]]==1)<50)return(NULL);z$.x<-if(x%in%binary_exposures)z[[x]] else as.numeric(scale(z[[x]]));z$.m<-as.numeric(scale(z[[m]]));if(!is.null(y)){z$.time<-z[[paste0(y,'.t2e')]];z$.event<-z[[paste0(y,'.Yt2e')]]};z}
a_formula<-function()reformulate(c('.x',covars),response='.m')
total_formula<-function()reformulate(c('.x',covars),response='Surv(.time,.event)')
direct_formula<-function()reformulate(c('.x','.m',covars),response='Surv(.time,.event)')
model_coef<-function(fit,term,type){if(is.null(fit))return(NULL);sm<-coef(summary(fit));cols<-if(type=='lm')c('Estimate','Std. Error','Pr(>|t|)')else c('coef','se(coef)','Pr(>|z|)');if(!term%in%rownames(sm)||any(!is.finite(sm[term,cols])))return(NULL);unname(sm[term,cols])}
screen_a<-function(d,x,m){z<-mediation_data(d,x,m);r<-tibble(mediator=m,N=if(is.null(z))NA_integer_ else nrow(z),a=NA_real_,p_a=NA_real_);if(is.null(z))return(r);aa<-model_coef(model_try(lm(a_formula(),z))$fit,'.x','lm');if(!is.null(aa)){r$a<-aa[1];r$p_a<-aa[3]};r}
screen_b<-function(d,x,m,y){z<-mediation_data(d,x,m,y);r<-tibble(mediator=m,N_b=if(is.null(z))NA_integer_ else nrow(z),b=NA_real_,p_b=NA_real_);if(is.null(z))return(r);bb<-model_coef(model_try(coxph(direct_formula(),z))$fit,'.m','cox');if(!is.null(bb)){r$b<-bb[1];r$p_b<-bb[3]};r}
empty_mediation<-function()tibble(exposure=character(),mediator=character(),outcome=character(),N=integer(),events=integer(),a_beta=double(),b_beta=double(),total_beta=double(),direct_beta=double(),indirect_beta=double(),p_sobel=double(),p_boot=double(),indirect_lo=double(),indirect_hi=double(),prop_mediated=double(),bootstrap_valid=integer(),exposure_unit=character(),status=character())
mediate_feature<-function(d,x,m,y,boot=100){z<-mediation_data(d,x,m,y);row<-tibble(exposure=x,mediator=m,outcome=y,N=if(is.null(z))NA_integer_ else nrow(z),events=if(is.null(z))NA_integer_ else sum(z$.event==1),a_beta=NA_real_,b_beta=NA_real_,total_beta=NA_real_,direct_beta=NA_real_,indirect_beta=NA_real_,p_sobel=NA_real_,p_boot=NA_real_,indirect_lo=NA_real_,indirect_hi=NA_real_,prop_mediated=NA_real_,bootstrap_valid=0L,exposure_unit=if(x%in%binary_exposures)'0 to 1 contrast' else 'per SD in complete-case mediation sample',status='skipped');if(is.null(z))return(row);fa<-model_coef(model_try(lm(a_formula(),z))$fit,'.x','lm');ft<-model_coef(model_try(coxph(total_formula(),z))$fit,'.x','cox');fd<-model_try(coxph(direct_formula(),z));b<-model_coef(fd$fit,'.m','cox');dr<-model_coef(fd$fit,'.x','cox');if(any(vapply(list(fa,ft,b,dr),is.null,logical(1)))){row$status<-'failed';return(row)};row$a_beta<-fa[1];row$b_beta<-b[1];row$total_beta<-ft[1];row$direct_beta<-dr[1];row$indirect_beta<-fa[1]*b[1];se<-sqrt(b[1]^2*fa[2]^2+fa[1]^2*b[2]^2);if(se>0)row$p_sobel<-2*pnorm(abs(row$indirect_beta/se),lower.tail=FALSE);if(abs(ft[1])>1e-6)row$prop_mediated<-row$indirect_beta/ft[1];bb<-rep(NA_real_,boot);for(i in seq_len(boot)){q<-z[sample.int(nrow(z),replace=TRUE),,drop=FALSE];aa<-model_coef(model_try(lm(a_formula(),q))$fit,'.x','lm');bt<-model_coef(model_try(coxph(direct_formula(),q))$fit,'.m','cox');if(!is.null(aa)&&!is.null(bt))bb[i]<-aa[1]*bt[1]};bb<-bb[is.finite(bb)];row$bootstrap_valid<-length(bb);if(boot>=50&&length(bb)>=max(50,ceiling(.8*boot))){row$p_boot<-min(1,2*min((sum(bb<=0)+1)/(length(bb)+1),(sum(bb>=0)+1)/(length(bb)+1)));row$indirect_lo<-quantile(bb,.025,names=FALSE);row$indirect_hi<-quantile(bb,.975,names=FALSE)};row$status<-'ok';row}
